function fewestSeatSwaps(row: number[]): number {
  const r = [...row];
  let swaps = 0;
  for (let i = 0; i < r.length; i += 2) {
    const want = r[i] ^ 1;
    if (r[i + 1] === want) continue;
    for (let j = i + 2; j < r.length; j++) {
      if (r[j] === want) { r[j] = r[i + 1]; r[i + 1] = want; swaps++; break; }
    }
  }
  return swaps;
}

