    def fewestSeatSwaps(self, row: List[int]) -> int:
        r = row[:]
        swaps = 0
        for i in range(0, len(r), 2):
            want = r[i] ^ 1
            if r[i + 1] == want:
                continue
            j = r.index(want, i + 2)
            r[i + 1], r[j] = r[j], r[i + 1]
            swaps += 1
        return swaps

