    def fewestSeatSwaps(self, row: List[int]) -> int:
        n = len(row) // 2
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        components = n
        for i in range(0, len(row), 2):
            a, b = find(row[i] >> 1), find(row[i + 1] >> 1)
            if a != b:
                parent[a] = b
                components -= 1
        return n - components

